import { Link } from "react-router-dom";
import useAuth from "../../context/userContext/useAuth";

export const RegisterForm = () => {
  const { register, message, error, loading } = useAuth();

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const userData: RegisterUser = {
      username: (form[0] as HTMLInputElement).value,
      email: (form[1] as HTMLInputElement).value,
      password: (form[2] as HTMLInputElement).value,
    };

    register(userData);
  };

  return (
    <section className="h-screen flex items-center justify-center bg-gray-100">
      <div className="container px-6 py-12">
        <div className="w-full max-w-md mx-auto">
          <form onSubmit={handleRegister} className="bg-white shadow-md rounded px-8 pt-6 pb-8 mb-4">
            <div className="mb-4">
              <input
                type="text"
                className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                placeholder="Username"
                disabled={loading}
              />
            </div>
            <div className="mb-4">
              <input
                type="email"
                className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                placeholder="Email address"
                disabled={loading}
              />
            </div>
            <div className="mb-6">
              <input
                type="password"
                className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 mb-3 leading-tight focus:outline-none focus:shadow-outline"
                placeholder="Password"
                disabled={loading}
              />
            </div>
            <div className="flex items-center justify-between mb-6">
              <Link
                to="/users/login"
                className="inline-block align-baseline font-bold text-sm text-blue-500 hover:text-blue-800"
              >
                Already have an account? Login!
              </Link>
            </div>
            <div className="flex items-center justify-between">
              <button
                type="submit"
                className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline w-full"
                disabled={loading}
              >
                Register
              </button>
            </div>
          </form>
          {message && (
            <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative" role="alert">
              <span className="block sm:inline">{message}</span>
            </div>
          )}
          {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
              <span className="block sm:inline">{error}</span>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};
